    }),
  } satisfies Prisma.discussion_board_articlesWhereInput;
  const tagFilter = props.body.tags && props.body.tags.length > 0;
  const data = await MyGlobal.prisma.discussion_board_articles.findMany({
    where: tagFilter
      ? {
          ...whereInput,
          tags: {
            some: {
              tag: {
                name: {
                  in: props.body.tags!,
                  mode: "insensitive",
                },
              },
            },
          },
        }
      : whereInput,
    skip,
    take: limit,
    orderBy: orderByInput,
