    where: whereInput,
    skip,
    take: limit,
    orderBy: orderByInput,
    ...DiscussionBoardBanAtSummaryTransformer.select(),
  });
  const total = await MyGlobal.prisma.discussion_board_bans.count({
    where: whereInput,
