import { postDiscussionBoardAuthMemberRefresh } from "../../../../providers/postDiscussionBoardAuthMemberRefresh";

@Controller("/discussionBoard/auth/member")
export class DiscussionboardAuthMemberController {
  /**
   * Register a new member account with email and password authentication.
   *
   * This endpoint creates a new member record in the discussion_board_members table with the provided email address, hashed password, display name, and optional biography text. The email address must be unique across all member accounts and will be used for all future authentication attempts.
   *
   * The password is hashed using bcrypt before being stored in the password_hash column, ensuring that plain text passwords are never persisted. The account status is initialized to 'active', allowing immediate login access.
   *
   * Upon successful registration, an email verification record is created in the discussion_board_member_email_verifications table with a unique token and expiration timestamp. This enables the email verification workflow to confirm the member's email address.
   *
   * The response includes JWT access and refresh tokens for immediate authenticated session establishment, along with the member's profile information including their id, email, display name, and bio.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Member registration information including email, password, and profile details
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Handle member registration by creating a new account in discussion_board_members table. Validate email uniqueness against existing members. Hash the password using bcrypt before storing in password_hash field. Initialize account status as 'active'. Create an email verification record in discussion_board_member_email_verifications table with a unique token and expiration timestamp. Return JWT access and refresh tokens along with member information. Handle duplicate email errors with appropriate validation response.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IDiscussionBoardMember.IJoin,
  ): Promise<IDiscussionBoardMember.IAuthorized> {
    try {
      return await postDiscussionBoardAuthMemberJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticate a member using email and password credentials.
   *
   * This endpoint validates the provided email address and password against the discussion_board_members table. The email is used to look up the member record, and the password is verified against the stored password_hash using bcrypt comparison.
   *
   * The authentication process checks that the member account status is 'active'. Accounts with status 'suspended' or 'deleted' will be rejected. The system also verifies that the member is not banned by checking the discussion_board_bans table - banned users cannot log in to the platform.
   *
   * Upon successful authentication, a new session record is created in the discussion_board_member_sessions table. This session captures the client's IP address, the page URL where authentication was initiated (href), and the HTTP referrer header value for security auditing purposes. The session includes an expiration timestamp for automatic invalidation.
   *
   * The response contains JWT access and refresh tokens that enable authenticated API access, along with the member's profile information including their id, email, display name, and bio.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Member login credentials with email and password
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Authenticate member credentials by looking up the discussion_board_members table by email. Verify the account status is 'active' and not 'suspended' or 'deleted'. Compare the provided password against the stored password_hash using bcrypt verification. Check if the member is banned by querying discussion_board_bans table. On successful authentication, create a new session record in discussion_board_member_sessions table with IP address, href, referrer, and expiration timestamp. Generate JWT access and refresh tokens. Return tokens with member information.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IDiscussionBoardMember.ILogin,
  ): Promise<IDiscussionBoardMember.IAuthorized> {
    try {
      return await postDiscussionBoardAuthMemberLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Refresh authentication tokens using a valid refresh token.
   *
   * This endpoint enables members to obtain new JWT access and refresh tokens without re-authenticating with their credentials. The provided refresh token is validated against the discussion_board_member_sessions table to ensure it corresponds to an active, non-expired session.
   *
   * The validation process checks that the session's expired_at timestamp has not passed. It also verifies that the associated member account in discussion_board_members still has status 'active' and has not been suspended or deleted. Additionally, the system confirms the member is not banned by checking the discussion_board_bans table.
   *
   * Upon successful validation, new JWT access and refresh tokens are generated with fresh expiration timestamps. The session may be updated with a new expiration time or a new session record may be created depending on the token rotation policy.
   *
   * The response contains the new JWT access and refresh tokens along with the member's current profile information including their id, email, display name, and bio. This enables seamless continuation of the authenticated session.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for obtaining new access and refresh tokens
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Validate the provided refresh token against the discussion_board_member_sessions table. Check that the session has not expired by comparing expired_at timestamp with current time. Verify the session belongs to an active member account by joining with discussion_board_members table. Check that the member status is 'active' and not banned. Generate new JWT access and refresh tokens with updated expiration. Optionally create a new session record or update the existing session's expired_at timestamp. Return new tokens with member information.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IDiscussionBoardMember.IRefresh,
  ): Promise<IDiscussionBoardMember.IAuthorized> {
    try {
      return await postDiscussionBoardAuthMemberRefresh({
        body,
      });
    } catch (error) {
