      return await postDiscussionBoardMemberArticlesArticleIdFiles({
        member,
        articleId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Remove a specific file attachment from an article.
   *
   * This operation removes a file attachment from an article by marking it as deleted using soft delete. Only the article's author or administrators can delete file attachments. When a file attachment is soft deleted, the associated file storage is also cleaned up to reclaim storage space.
   *
   * The operation validates that the specified file belongs to the specified article before deletion. This prevents accidental deletion of files from wrong articles and ensures referential integrity.
